targets = ["src/a.txt", "src/nested/b.txt"]
for p in targets:
    before = repo.read(p)
    repo.edit(p, "OldClient", "NewClient", all=True)
    after = repo.read(p)
    return_data = {"path": p, "before": repr(before), "after": repr(after)}
    # verify
    if "OldClient" in after:
        fail("still contains OldClient in %s" % p)
    if after.count("NewClient") != before.count("OldClient"):
        fail("count mismatch in %s" % p)
    # verify length preserved
    if len(after) != len(before):
        fail("length changed in %s" % p)
return {"edits": [return_data], "status": repo.status(), "diff": repo.diff()}
